body.script:
//
					const cfg      = document.getElementById('cfg').dataset;
					const ASSET    = cfg.asset;
					// Candles are Deribit perpetual futures on this page only
					// (see dankbit.trade.get_candles_deribit_perpetual) —
					// mirrors the server-side
					// _DERIBIT_PERPETUAL_SYMBOL_MAP.
					const DERIBIT_PERP_SYMBOL = { BTC: 'BTC-PERPETUAL', ETH: 'ETH-PERPETUAL' }[ASSET] || (ASSET + '-PERPETUAL');
					document.getElementById('exchange-label').textContent = 'Deribit · ' + DERIBIT_PERP_SYMBOL;
					// Recomputed from scratch on every request (no persisted
					// history behind this page at all — see
					// ChartController.gamma_triple_json) — polls on the same
					// general dankbit.refresh_interval every other page's
					// own refresh rate uses, so the lines visibly move on
					// the cadence the user actually configures.
					const REFRESH = parseInt(cfg.refresh, 10) * 1000;
					let   INTERVAL = '4h';
					// Trade window (hours) the 3 gamma_band lines are
					// computed over — the "Window" dropdown, mirrored
					// server-side by ChartController.gamma_triple_json's
					// own ?hours= handling.
					let   WINDOW_HOURS = 12;
					// Deribit perpetual futures, not Binance spot —
					// /gt/<asset> only, per product decision; every other
					// TradingView page in this addon keeps reading candles
					// from /api/klines/<asset> (Binance spot, see
					// ChartController.klines_proxy).
					const klineUrl = (iv, limit) => '/api/klines-futures/' + ASSET + '?interval=' + iv + '&limit=' + limit;
					const gammaTripleUrl = h => '/api/gamma-triple/' + ASSET + '?hours=' + h;
					// Same "Last trade:" footer field the Delta Chart uses —
					// a growing gap between this and "now" is the at-a-glance
					// signal that dankbit_ws has stalled (its DB connection
					// can die without crashing the container, silently
					// dropping every trade — see dankbit_ws_batch.py).
					const LAST_TRADE_URL = '/api/last-trade/' + ASSET;
					let   lastTradeTs = null;

					// Shown in real UTC (not a browser-local shift) — this is a
					// staleness check against server time, not a chart position.
					function formatLastTradeTs(iso) {
						if (!iso) return null;
						return new Date(iso).toLocaleString('de-DE', {
							timeZone: 'UTC',
							year: 'numeric', month: '2-digit', day: '2-digit',
							hour: '2-digit', minute: '2-digit', second: '2-digit',
						}) + ' UTC';
					}

					// Same browser-local-timezone shift every other TV chart page
					// in this addon applies — Lightweight Charts always renders
					// epoch seconds as UTC wall-clock time, so every timestamp fed
					// into the chart is pre-shifted by the viewer's own current
					// UTC offset first.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					// Black would vanish into the dark-mode chart background
					// (#000000), so a "black" line swaps to a lighter gray
					// there instead — same axisBlack()-style convention every
					// other "plain black" line in this addon uses (see
					// dankbit_templates.xml, /4l/<asset>'s own LC/LP lines).
					function axisBlack() { return DARK_MODE ? '#e8e8e8' : '#000000'; }
					// Line/label color is driven by that line's own dominant
					// leg (LC/LP/SC/SP — see _gamma_triple_dominant_leg()),
					// not a fixed per-position hue: LC/LP dominant -> black
					// (same convention /4l/<asset>'s own LC/LP lines use),
					// SC/SP dominant -> orange (same convention /4l/<asset>'s
					// own SC/SP lines use). Falls back to axisBlack() when
					// there's no dominant leg at all (nothing computable at
					// that expiry_index).
					function legColor(leg) { return (leg === 'SC' || leg === 'SP') ? '#fb8c00' : axisBlack(); }
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					window.addEventListener('resize', () => {
						chart.resize(window.innerWidth, window.innerHeight);
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// The 3 indicators on this page are horizontal price lines,
					// not connected time-series points — nothing is persisted
					// anywhere (see ChartController.gamma_triple_json), each
					// poll just recomputes the 3 current values fresh and
					// redraws the lines at their new levels.
					let nearestPriceLine      = null;
					let nearestPlus1PriceLine = null;
					let nearestPlus2PriceLine = null;

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function showSpinner() { document.getElementById('spinner').style.display = 'block'; }
					function hideSpinner() { document.getElementById('spinner').style.display = 'none'; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					// 500 bars is the flat fetch size loadCandles() always
					// uses regardless of timeframe (see below) — 15m's own
					// window is capped under that (500 * 15m ≈ 5.2 days)
					// rather than the wider defaults 1h/4h/1d use.
					const TF_WINDOW = { '15m': 5, '1h': 30, '4h': 15, '1d': 365 };
					const BARS_PER_DAY = { '15m': 96, '1h': 24, '4h': 6, '1d': 1 };

					let realCandles = [];

					function applyVisibleRange() {
						const days = TF_WINDOW[INTERVAL] || 21;
						const barsPerDay = BARS_PER_DAY[INTERVAL] || 24;
						const lastIndex = realCandles.length - 1;
						chart.timeScale().setVisibleLogicalRange({
							from: lastIndex - days * barsPerDay,
							to:   lastIndex,
						});
					}

					// Right-click "Reset chart view" — mirrors original TradingView's
					// context-menu item, same as the Delta Chart/Gamma Chart:
					// re-autoscales the price axis (undoes any manual drag-zoom on
					// the price scale) and restores the default time-scale window
					// for the current timeframe (undoes any pan/zoom on the time
					// axis), without touching series data or any indicator state.
					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					// Custom context menu (Lightweight Charts has no built-in one) —
					// right-clicking the chart area shows a single "Reset chart view"
					// item at the cursor, clamped so it never renders off-screen.
					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					// Right-clicking outside the chart area (e.g. the toolbar) falls
					// through to the browser's own native context menu — hide ours
					// first so it doesn't linger open underneath it.
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						series.setData(realCandles);
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						series.setData(realCandles);
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
					}

					function windowStatusLabel() {
						return WINDOW_HOURS + 'h trailing window';
					}

					function lastTradeSuffix() {
						const label = formatLastTradeTs(lastTradeTs);
						return label ? '  ·  Last trade: ' + label : '';
					}

					function statusText() {
						return ASSET + ' · Gamma Triple (' + windowStatusLabel() + ', live)' + lastTradeSuffix();
					}

					async function refreshLastTrade() {
						const data = await (await fetch(LAST_TRADE_URL)).json();
						lastTradeTs = data.last_trade_ts || null;
						setStatus(statusText());
					}

					async function setWindow(h) {
						WINDOW_HOURS = parseInt(h, 10);
						setStatus(statusText());
						await refreshGammaTriple();
					}

					// Shows #spinner for the duration of the fetch — this
					// endpoint recomputes the whole curve fresh server-side on
					// every call (no persisted history behind this page), so it
					// can take noticeably longer than the plain klines poll.
					// Hidden in a finally so a fetch error still clears it
					// rather than leaving it spinning forever.
					async function refreshGammaTriple() {
						showSpinner();
						try {
							const data = await (await fetch(gammaTripleUrl(WINDOW_HOURS))).json();

							if (nearestPriceLine)      { series.removePriceLine(nearestPriceLine);      nearestPriceLine      = null; }
							if (nearestPlus1PriceLine) { series.removePriceLine(nearestPlus1PriceLine); nearestPlus1PriceLine = null; }
							if (nearestPlus2PriceLine) { series.removePriceLine(nearestPlus2PriceLine); nearestPlus2PriceLine = null; }

							// Gamma regime marker (+/- prefix on the title) — whether
							// this line's own gamma_band value is positive or
							// negative, same +/- convention the Delta Chart's
							// High/Resistance-Low/Support markers use, just baked
							// into the title text here since createPriceLine has
							// no separate marker API the way a line series does.
							//
							// Dominant-leg suffix (LC/LP/SC/SP) — which of that
							// expiry's 4 gamma extrema (Buyer Call/Buyer Put/
							// Seller Call/Seller Put) has the largest abs
							// magnitude, from ChartController.
							// _gamma_triple_dominant_leg() server-side; appended
							// to the end of the title as plain text, same as
							// every other label suffix on this chart, since
							// createPriceLine has no separate subtitle slot.
							// Followed by that leg's own Abs value (already
							// rounded server-side, same /1e6 scaling the
							// /<instrument>/zones page's own Abs. lines use) —
							// the number behind the dominant leg, not the
							// gamma_band price the line itself is drawn at.
							//
							// axisLabelColor matches each line's own color here
							// (unlike most other price lines in this addon, which
							// force a black axis label regardless of line color).
							// Color itself is picked per-line via legColor(), based
							// on that line's own dominant leg, not a fixed
							// per-position hue (see legColor() above).
							function dominantLegSuffix(leg, value) { return leg ? ' ' + leg + ' ' + value : ''; }
							if (data.nearest_gamma_band) {
								const sign = data.nearest_gamma_band >= 0 ? '+' : '-';
								const color = legColor(data.nearest_dominant_leg);
								nearestPriceLine = series.createPriceLine({
									price: data.nearest_gamma_band, color: color, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: color,
									title: sign + ' Nearest' + (data.nearest_instrument ? ' ' + data.nearest_instrument : '') + dominantLegSuffix(data.nearest_dominant_leg, data.nearest_dominant_leg_value),
								});
							}
							if (data.nearest_plus_1_gamma_band) {
								const sign = data.nearest_plus_1_gamma_band >= 0 ? '+' : '-';
								const color = legColor(data.nearest_plus_1_dominant_leg);
								nearestPlus1PriceLine = series.createPriceLine({
									price: data.nearest_plus_1_gamma_band, color: color, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: color,
									title: sign + ' Nearest+1' + (data.nearest_plus_1_instrument ? ' ' + data.nearest_plus_1_instrument : '') + dominantLegSuffix(data.nearest_plus_1_dominant_leg, data.nearest_plus_1_dominant_leg_value),
								});
							}
							if (data.nearest_plus_2_gamma_band) {
								const sign = data.nearest_plus_2_gamma_band >= 0 ? '+' : '-';
								const color = legColor(data.nearest_plus_2_dominant_leg);
								nearestPlus2PriceLine = series.createPriceLine({
									price: data.nearest_plus_2_gamma_band, color: color, lineWidth: 2,
									lineStyle: LightweightCharts.LineStyle.Solid,
									axisLabelVisible: true, axisLabelColor: color,
									title: sign + ' Nearest+2' + (data.nearest_plus_2_instrument ? ' ' + data.nearest_plus_2_instrument : '') + dominantLegSuffix(data.nearest_plus_2_dominant_leg, data.nearest_plus_2_dominant_leg_value),
								});
							}
						} finally {
							hideSpinner();
						}
					}

					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: DARK_MODE ? '#e8e8e8' : '#000000', title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function init() {
						try {
							await loadCandles();
							await refreshGammaTriple();
							await refreshLastTrade();
							setStatus(statusText());
						}
						catch (e) { setStatus('Error: ' + e.message); }
					}
					init();
					setInterval(updateLatestCandle, 5000);
					setInterval(refreshGammaTriple, REFRESH);
					setInterval(refreshLastTrade, REFRESH);
				//
